import { expect, expectStatus, test } from "../../fixtures";

test(
  "search and the status filter apply together",
  { tag: "@LIF-14" },
  async ({ apiAs }) => {
    // Arrange: a unique word shared by two vendor names so parallel runs don't collide.
    const member = await apiAs("member");
    const word = `lifecycle${Date.now()}${Math.random().toString(36).slice(2, 8)}`;

    const draftResponse = await member.post("/api/vendors", {
      data: {
        name: `${word} Draft Co`,
        category: "services",
        contact_email: `${word}-draft@example.test`,
      },
    });
    const draft = await expectStatus<{ id: string; status: string }>(draftResponse, 201);

    const reviewResponse = await member.post("/api/vendors", {
      data: {
        name: `${word} Review Co`,
        category: "services",
        contact_email: `${word}-review@example.test`,
      },
    });
    const toReview = await expectStatus<{ id: string; status: string }>(reviewResponse, 201);

    // Submit only the second vendor so it moves into review.
    const submitResponse = await member.post(`/api/vendors/${toReview.id}/submit`);
    const submitted = await expectStatus<{ id: string; status: string }>(submitResponse, 200);
    expect(submitted.status).toBe("in_review");

    // Act: search by the shared word and filter to in_review.
    const listResponse = await member.get("/api/vendors", {
      params: { q: word, status: "in_review" },
    });

    // Assert: exactly the vendor in review, and the total agrees.
    const page = await expectStatus<{
      items: { id: string; name: string; status: string }[];
      total: number;
      limit: number;
      offset: number;
    }>(listResponse, 200);

    expect(page.total).toBe(1);
    expect(page.items).toHaveLength(1);
    expect(page.items[0].id).toBe(toReview.id);
    expect(page.items[0].id).not.toBe(draft.id);
    expect(page.items[0].status).toBe("in_review");
  },
);
